const crypto = require('crypto');
const item = $input.first();
// n8n 的 Raw Body 位于 binary.data，验签不能重新序列化解析后的 JSON。
const binaryBody = item.binary?.data?.data;
const raw = typeof binaryBody === 'string'
  ? Buffer.from(binaryBody, 'base64').toString('utf8')
  : item.json.rawBody ?? (typeof item.json.body === 'string' ? item.json.body : '');
if (!raw) throw new Error('缺少社交 webhook 原始正文');
const headers = item.json.headers ?? {};
const supplied = headers['x-msime-signature'] ?? headers['X-MSIME-Signature'] ?? '';
const secret = $env.MSIME_SOCIAL_WEBHOOK_SECRET ?? '';
if (!secret || !supplied) throw new Error('缺少社交 webhook 签名');
const expected = `sha256=${crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex')}`;
if (supplied.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(supplied), Buffer.from(expected))) {
  throw new Error('社交 webhook 签名无效');
}

let payload;
try {
  payload = JSON.parse(raw);
} catch (error) {
  throw new Error('社交 webhook 正文不是 JSON');
}
if (payload.schema_version !== 1 || payload.event !== 'release.published') {
  throw new Error('社交 webhook 事件类型不支持');
}
const release = payload.release ?? {};
const version = String(release.tag ?? '').replace(/^backend-/, '');
const body = String(release.body ?? '').replace(/```[\s\S]*?```/g, '').trim();
const bullets = body.split(/\r?\n/).map((line) => line.trim()).filter((line) => /^[-*] /.test(line)).slice(0, 3).map((line) => `• ${line.slice(2).trim()}`);
const highlights = bullets.join('\n') || '查看本版更新内容';
const url = String(release.url ?? '');
const landing = String($env.MSIME_SOCIAL_SITE_URL ?? 'https://msime.app/download/');
if (!/^https:\/\/[^/?#\s@]+(?:\/[^?#\s]*)?$/.test(landing)) throw new Error('社交官网入口必须是无查询参数的 HTTPS 地址');
const campaign = `${String(release.tag ?? 'release').replace(/[^a-zA-Z0-9._~-]/g, '-').slice(0, 100)}-${crypto.createHash('sha256').update(String(payload.idempotency_key)).digest('hex').slice(0, 12)}`;
const trackedUrl = channel => `${landing}?utm_source=${encodeURIComponent(channel)}&utm_medium=social&utm_campaign=${campaign}`;
const truncate = (text, length) => text.length <= length ? text : `${text.slice(0, length - 1)}…`;
// 先为完整链接预留长度，更新内容再长也不能把推广入口截断。
const post = (channel, length, full = false) => {
  const content = `水杉输入法后端 ${version} 已发布。\n\n${full ? (body || '本版更新内容见 Release 说明。') : highlights}`;
  const links = `\n\n下载：${trackedUrl(channel)}${full ? `\n更新说明：${url}` : ''}`;
  if (links.length >= length) throw new Error('社交链接超过平台长度限制');
  return truncate(content, length - links.length) + links;
};
const enabled = (flag, ...values) => $env[flag] === '1' && values.every(Boolean);
const state = $getWorkflowStaticData('global');
const completed = state.completed ?? {};
const pending = (channel) => !completed[payload.idempotency_key]?.[channel];
const out = [];
if (enabled('MSIME_TELEGRAM_ENABLED', $env.MSIME_TELEGRAM_BOT_TOKEN, $env.MSIME_TELEGRAM_CHAT_ID) && pending('telegram')) out.push({json: {channel: 'telegram', idempotency_key: payload.idempotency_key, tracking_url: trackedUrl('telegram'), text: post('telegram', 4096, true)}});
if (enabled('MSIME_DISCORD_ENABLED', $env.MSIME_DISCORD_WEBHOOK_URL) && pending('discord')) out.push({json: {channel: 'discord', idempotency_key: payload.idempotency_key, tracking_url: trackedUrl('discord'), text: post('discord', 2000, true)}});
if (enabled('MSIME_MASTODON_ENABLED', $env.MSIME_MASTODON_INSTANCE, $env.MSIME_MASTODON_ACCESS_TOKEN) && pending('mastodon')) out.push({json: {channel: 'mastodon', idempotency_key: payload.idempotency_key, tracking_url: trackedUrl('mastodon'), text: post('mastodon', 500)}});
if (enabled('MSIME_BLUESKY_ENABLED', $env.MSIME_BLUESKY_IDENTIFIER, $env.MSIME_BLUESKY_APP_PASSWORD) && pending('bluesky')) out.push({json: {channel: 'bluesky', idempotency_key: payload.idempotency_key, tracking_url: trackedUrl('bluesky'), text: post('bluesky', 300)}});
if (enabled('MSIME_X_ENABLED') && pending('x')) out.push({json: {channel: 'x', idempotency_key: payload.idempotency_key, tracking_url: trackedUrl('x'), text: post('x', 280)}});
if (enabled('MSIME_REDDIT_ENABLED', $env.MSIME_REDDIT_ACCESS_TOKEN, $env.MSIME_REDDIT_SUBREDDIT, $env.MSIME_REDDIT_USER_AGENT) && pending('reddit')) out.push({json: {channel: 'reddit', idempotency_key: payload.idempotency_key, title: truncate(`水杉输入法后端 ${version} 发布`, 300), text: post('reddit', 40000, true), url: trackedUrl('reddit'), tracking_url: trackedUrl('reddit')}});
return out;

const source = $('验签和生成文案').item.json;
const response = $json;
const failed = Boolean(response.error) || Number(response.statusCode ?? 200) >= 400;
if (!failed) {
  const state = $getWorkflowStaticData('global');
  state.completed ??= {};
  state.completed[source.idempotency_key] ??= {};
  state.completed[source.idempotency_key]['telegram'] = new Date().toISOString();
}
return [{json: {channel: 'telegram', ok: !failed}}];

